//! Immutable native Box3D construction images, generated by nonconvex-build.c.
use serde_json::Value;
use shallot_physics::{height_build, math::Vec3, mesh_build};
struct Case {
    name: String,
    operation: u32,
    args: Vec<u32>,
    vertices: Option<Vec<u32>>,
    indices: Option<Vec<u32>>,
    heights: Option<Vec<u32>>,
    materials: Option<Vec<u8>>,
    words: Option<Vec<u32>>,
}
#[test]
fn mesh_gold() {
    check(false);
}
#[test]
fn height_field_gold() {
    check(true);
}
fn check(height_field: bool) {
    let gold: Value = serde_json::from_str(include_str!("nonconvex_build.gold.json")).unwrap();
    let cases: Vec<Case> = gold
        .as_array()
        .unwrap()
        .iter()
        .map(|c| {
            let words = |key: &str| {
                c[key].as_array().map(|a| {
                    a.iter()
                        .map(|x| x.as_u64().unwrap() as u32)
                        .collect::<Vec<_>>()
                })
            };
            Case {
                name: c["name"].as_str().unwrap().to_owned(),
                operation: c["operation"].as_u64().unwrap() as u32,
                args: words("args").unwrap(),
                vertices: words("vertices"),
                indices: words("indices"),
                heights: words("heights"),
                materials: words("materials").map(|a| a.into_iter().map(|x| x as u8).collect()),
                words: words("words"),
            }
        })
        .collect();
    for c in cases
        .into_iter()
        .filter(|c| (c.operation >= 10) == height_field)
    {
        let a: Vec<f32> = c.args.iter().map(|&x| f32::from_bits(x)).collect();
        let v = |i: usize| Vec3::new(a[i], a[i + 1], a[i + 2]);
        let image = match c.operation {
            0 => {
                let vertices: Vec<Vec3> = c
                    .vertices
                    .as_ref()
                    .unwrap()
                    .as_chunks::<3>()
                    .0
                    .iter()
                    .map(|p| {
                        Vec3::new(
                            f32::from_bits(p[0]),
                            f32::from_bits(p[1]),
                            f32::from_bits(p[2]),
                        )
                    })
                    .collect();
                mesh_build::create_mesh(&mesh_build::Definition {
                    vertices: &vertices,
                    indices: c.indices.as_ref().unwrap(),
                    materials: c.materials.as_ref().unwrap(),
                    weld_tolerance: a[0],
                    weld: a[1] != 0.0,
                    median: a[2] != 0.0,
                    edges: a[3] != 0.0,
                    clockwise: false,
                })
            }
            1 => mesh_build::create_box(v(0), v(3), a[6] != 0.0, false),
            2 => mesh_build::create_box(v(0), v(3), true, true),
            3 => mesh_build::create_grid(
                a[0] as usize,
                a[1] as usize,
                a[2],
                a[3] as usize,
                a[4] != 0.0,
            ),
            4 => mesh_build::create_wave(a[0] as usize, a[1] as usize, a[2], a[3], a[4], a[5]),
            5 => mesh_build::create_torus(a[0] as usize, a[1] as usize, a[2], a[3]),
            10 => {
                let heights: Vec<f32> = c
                    .heights
                    .as_ref()
                    .unwrap()
                    .iter()
                    .map(|&x| f32::from_bits(x))
                    .collect();
                Some(height_build::create_height_field(
                    &height_build::Definition {
                        heights: &heights,
                        materials: c.materials.as_ref().unwrap(),
                        columns: a[0] as usize,
                        rows: a[1] as usize,
                        scale: v(2),
                        minimum: a[5],
                        maximum: a[6],
                        clockwise: a[7] != 0.0,
                    },
                ))
            }
            11 => Some(height_build::create_grid(
                a[0] as usize,
                a[1] as usize,
                v(2),
                a[5] != 0.0,
            )),
            12 => Some(height_build::create_wave(
                a[0] as usize,
                a[1] as usize,
                v(2),
                a[5],
                a[6],
                a[7] != 0.0,
            )),
            _ => unreachable!(),
        };
        match (image, c.words) {
            (None, None) => {}
            (Some(image), Some(words)) => {
                let actual: Vec<u32> = image
                    .bytes()
                    .as_chunks::<4>()
                    .0
                    .iter()
                    .map(|w| u32::from_le_bytes(*w))
                    .collect();
                assert_eq!(actual.len(), words.len(), "{} word count", c.name);
                // Report the first differing word rather than dumping entire geometry images.
                for (i, (a, b)) in actual.iter().zip(&words).enumerate() {
                    assert_eq!(a, b, "{} word {}", c.name, i);
                }
            }
            _ => panic!("{} null mismatch", c.name),
        }
    }
}
